package org.synqoria.scheduling;
import org.synqoria.security.TrustedAccessContext;import java.time.*;import java.util.*;
public class AppointmentCancellationPreflightTest{public static void main(String[]a){int n=0;var t=UUID.randomUUID();var f=UUID.randomUUID();var p=UUID.randomUUID();var b=new AppointmentAggregate(UUID.randomUUID(),t,f,p,UUID.randomUUID(),new AppointmentWindow(Instant.parse("2026-11-01T09:00:00Z"),Instant.parse("2026-11-01T10:00:00Z"),ZoneId.of("UTC")),AppointmentAggregate.State.REQUESTED,1,null);var c=new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of("appointment:manage"),Set.of(p));var s=new AppointmentCancellationPreflight();var d=s.prepare(c,b,1,"Requested by patient");check(d.proposed().state()==AppointmentAggregate.State.CANCELLED);n++;check(d.proposed().reason().equals("Requested by patient"));n++;check(d.event().aggregateVersion()==2);n++;check(!d.event().payloadSha256().equals(s.prepare(c,b,1,"Other reason").event().payloadSha256()));n++;check(s.prepare(c,b,2,"reason").outcome()==AppointmentCancellationPreflight.Outcome.STALE);n++;check(s.prepare(c,b,1," ").proposed()==null);n++;check(s.prepare(c,b,1,"x".repeat(501)).proposed()==null);n++;check(s.prepare(null,b,1,"reason").event()==null);n++;check(s.prepare(c,d.proposed(),2,"reason").outcome()==AppointmentCancellationPreflight.Outcome.INVALID_STATE);n++;System.out.println("PASS "+n+" cancellation assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
